package com.updatetracker.update_tracker.controller;
import com.updatetracker.update_tracker.dto.*; import com.updatetracker.update_tracker.model.*; import com.updatetracker.update_tracker.service.AdminService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasRole('ADMIN')") public class AdminController {private final AdminService service;public AdminController(AdminService s){service=s;} @PostMapping("/users") public User createUser(@Valid @RequestBody CreateUserRequest r){return service.createUser(r);} @PostMapping("/projects") public Project createProject(@Valid @RequestBody CreateProjectRequest r){return service.createProject(r);} @PostMapping("/users/{userId}/projects/{projectId}") public void assign(@PathVariable Long userId,@PathVariable Long projectId){service.assignProject(userId,projectId);}}
